var canPermutePalindrome = function(s) {
    const map = new Map();
    for (const ch of s) {
        map.set(ch, (map.get(ch) || 0) + 1);
    }
    let odd = 0;
    for (const cnt of map.values()) {
        if (cnt % 2 === 1) odd++;
    }
    return odd <= 1;
};
